      document.getElementById('territoryFacts').innerHTML=`<b>${esc(selected.agente)} · ${esc(selected.creLabel)}</b><br>${selected.unidades} unidade${selected.unidades===1?'':'s'} acompanhada${selected.unidades===1?'':'s'} · ${selected.exclusivas} exclusiva${selected.exclusivas===1?'':'s'}.`;
      const query=norm(document.getElementById('territorySearch').value),filtered=query?units.filter(record=>recordText(record).includes(query)):units;
      table('territoryTable',filtered,[['creLabel','CRE'],['unidade','Unidade'],['planoAcao','Plano de Ação'],['planoDimensao','Plano de Dimensão'],['exclusiva','Exclusiva'],['bairro','Bairro']]);
