  geoBuildSomIndex=function(){
    const rows=Array.isArray(SOM_ROWS)?SOM_ROWS:[];
    if(GEO_STATE.somIndexSize===rows.length&&GEO_STATE.somIndex.size)return;
    GEO_STATE.somIndex=new Map();
    rows.forEach(row=>{
      const schoolRef=row.codigoSME?`${row.codigoSME} ${row.escola||''}`:(row.escola||'');const point=geoFindPointForSchool(schoolRef,row.cre||row.regional);if(!point)return;
      const key=norm(point.name);if(!GEO_STATE.somIndex.has(key))GEO_STATE.somIndex.set(key,[]);GEO_STATE.somIndex.get(key).push(row);
    });
    GEO_STATE.somIndexSize=rows.length;GEO_STATE.evalCache.clear();
  };
  GEO_STATE.somIndex=new Map();GEO_STATE.somIndexSize=-1;

  geoBuildAdrIndex=function(callback){
    if(typeof callback==='function')GEO_STATE.adrCallbacks.push(callback);
    if(GEO_STATE.adrReady){const callbacks=GEO_STATE.adrCallbacks.splice(0);callbacks.forEach(fn=>fn());return}
    if(GEO_STATE.adrBuilding)return;
    GEO_STATE.adrBuilding=true;
    const rows=Array.isArray(ADR_ROWS)?ADR_ROWS:[],schoolCache=new Map();let index=0;
    const add=(aggregate,field,value)=>{const number=Number(value);if(Number.isFinite(number)){aggregate[field+'S']+=number;aggregate[field+'N']++}};
    const step=()=>{
      const limit=Math.min(index+350,rows.length);
      for(;index<limit;index++){
        const row=rows[index];if(!row||(row.adr!=='ADR 1'&&row.adr!=='ADR 2'))continue;
        const raw=String(row.escola||''),cacheKey=`${row.cre||row.regional||''}\u0001${raw}`;let point=schoolCache.get(cacheKey);
        if(point===undefined){point=geoFindPointForSchool(raw,row.cre||row.regional)||null;schoolCache.set(cacheKey,point)}
        if(!point)continue;
        const key=geoAdrIndexKey(point.name,row.ano,row.componente,row.adr);let aggregate=GEO_STATE.adrIndex.get(key);
        if(!aggregate){aggregate={adequadoS:0,adequadoN:0,abaixoS:0,abaixoN:0,basicoS:0,basicoN:0,avaliadosPctS:0,avaliadosPctN:0};GEO_STATE.adrIndex.set(key,aggregate)}
        add(aggregate,'adequado',row.adequado);add(aggregate,'abaixo',row.abaixo);add(aggregate,'basico',row.basico);add(aggregate,'avaliadosPct',row.avaliadosPct);
      }
      if(index<rows.length){setTimeout(step,0);return}
      GEO_STATE.adrReady=true;GEO_STATE.adrBuilding=false;GEO_STATE.evolutionCache.clear();GEO_STATE.evalCache.clear();geoUpdateContextUI();geoRenderMarkers();
      const callbacks=GEO_STATE.adrCallbacks.splice(0);callbacks.forEach(fn=>{try{fn()}catch(error){console.error(error)}});
    };
    setTimeout(step,0);
  };

  function rebuildAdrIndexRegionAware(){
    const waitForPrevious=setInterval(()=>{
      if(GEO_STATE.adrBuilding)return;
      clearInterval(waitForPrevious);
      GEO_STATE.adrIndex=new Map();GEO_STATE.adrReady=false;GEO_STATE.evalCache.clear();GEO_STATE.evolutionCache.clear();geoBuildAdrIndex();
    },50);
  }

  geoLatestEdition=function(modality,segment='',component=''){
    const rows=(Array.isArray(SOM_ROWS)?SOM_ROWS:[]).filter(row=>{
      if(row.modalidade!==modality||!geoRowInScope(row))return false;
      if(segment&&!geoRowMatchesYearFilter(row.anoEscolar,segment))return false;
      if(component&&typeof somComponentMatches==='function'&&!somComponentMatches(row.componente,component,row.modalidade))return false;
      return true;
    });
    const editions=[...new Set(rows.map(row=>String(row.edicao||'').trim()).filter(Boolean))];
    editions.sort((a,b)=>typeof somOrderEdicao==='function'?somOrderEdicao(b)-somOrderEdicao(a):String(b).localeCompare(String(a),'pt-BR',{numeric:true}));
    return editions[0]||'';
  };
  geoRowsForEvaluationFilters=function(evaluation,segment='',component=''){
    if(evaluation==='ADR')return [];
    return (Array.isArray(SOM_ROWS)?SOM_ROWS:[]).filter(row=>row.modalidade===evaluation&&geoRowInScope(row)&&(!segment||geoRowMatchesYearFilter(row.anoEscolar,segment))&&(!component||typeof somComponentMatches!=='function'||somComponentMatches(row.componente,component,row.modalidade)));
  };
  geoAdrSnapshot=function(ctx){
    const scope=geoScopePoints(),cacheKey=['V140_ADR',GEO_STATE.region,ctx.adrView,ctx.segment,ctx.component,ctx.indicator,GEO_STATE.adrReady].join('\u0002'),cached=GEO_STATE.evalCache.get(cacheKey);if(cached)return cached;
    const results=new Map();
    if(!GEO_STATE.adrReady){scope.forEach(point=>results.set(point.name,{status:'loading',delta:null,value:null,count:0}));const snapshot={results,median:null,count:0};GEO_STATE.evalCache.set(cacheKey,snapshot);return snapshot}
    if(ctx.adrView==='progress'){scope.forEach(point=>results.set(point.name,geoAdrMetricForPoint(point,ctx)));const snapshot={results,median:null,count:[...results.values()].filter(result=>Number.isFinite(Number(result.value))&&result.count>0).length};GEO_STATE.evalCache.set(cacheKey,snapshot);return snapshot}
    const adrName=ctx.adrView==='adr1'?'ADR 1':'ADR 2',values=new Map();scope.forEach(point=>{const value=geoAdrSingleValueForPoint(point,ctx,adrName);if(Number.isFinite(value))values.set(point.name,value)});
    const median=geoMedian([...values.values()]),threshold=.5;
    scope.forEach(point=>{const value=values.get(point.name);if(!Number.isFinite(value)||!Number.isFinite(median)){results.set(point.name,{status:'nodata',delta:null,value:null,median,count:0,suffix:'%'});return}const inverse=ctx.indicator==='abaixo',rawDelta=value-median,directional=inverse?-rawDelta:rawDelta,status=Math.abs(directional)<=threshold?'flat':directional>0?'up':'down',bandLabel=status==='flat'?'Próximo da mediana':inverse?(status==='up'?'Abaixo da mediana':'Acima da mediana'):(status==='up'?'Acima da mediana':'Abaixo da mediana');results.set(point.name,{status,delta:directional,rawDelta,value,median,count:1,suffix:'%',bandLabel})});
    const snapshot={results,median,count:values.size};GEO_STATE.evalCache.set(cacheKey,snapshot);return snapshot;
  };
  geoSomSnapshot=function(ctx){
    const scope=geoScopePoints(),cacheKey=['V140_SOM',GEO_STATE.region,ctx.evaluation,ctx.segment,ctx.component,ctx.indicator,ctx.edition,GEO_STATE.somIndexSize,Array.isArray(SOM_ROWS)?SOM_ROWS.length:0].join('\u0002'),cached=GEO_STATE.evalCache.get(cacheKey);if(cached)return cached;
    geoBuildSomIndex();const isAvalia=ctx.evaluation==='Avalia RJ',isIdeb=ctx.evaluation==='IDEB 2025',isIdebGrowth=isIdeb&&ctx.indicator==='crescimento',values=new Map();
    scope.forEach(point=>{const rows=geoSomRowsForPoint(point,ctx),value=geoWeightedEval(rows,row=>geoSomMetricValue(row,ctx));if(Number.isFinite(value))values.set(point.name,value)});
    const all=[...values.values()],median=isIdebGrowth?null:geoMedian(all),quartiles=isAvalia?{q1:geoQuantile(all,.25),q2:geoQuantile(all,.5),q3:geoQuantile(all,.75)}:null,inverse=ctx.indicator==='abaixo',threshold=isIdeb?.05:.5,suffix=isIdeb?'':'%',results=new Map();
    scope.forEach(point=>{const value=values.get(point.name);if(!Number.isFinite(value)){results.set(point.name,{status:'nodata',delta:null,value:null,median,count:0,suffix,quartiles});return}if(isAvalia&&quartiles&&[quartiles.q1,quartiles.q2,quartiles.q3].every(Number.isFinite)){let status='excellent',bandLabel='Excelente';if(value<=quartiles.q1){status='down';bandLabel='Crítica'}else if(value<=quartiles.q2){status='attention';bandLabel='Atenção'}else if(value<=quartiles.q3){status='up';bandLabel='Bom desempenho'}results.set(point.name,{status,delta:null,value,median,count:1,suffix:'%',quartiles,bandLabel});return}if(isIdebGrowth){const status=Math.abs(value)<=threshold?'flat':value>0?'up':'down';results.set(point.name,{status,delta:value,value,median:null,count:1,suffix:'',bandLabel:status==='up'?'Subiu':status==='down'?'Caiu':'Estável'});return}if(!Number.isFinite(median)){results.set(point.name,{status:'nodata',delta:null,value:null,median,count:0,suffix});return}const directional=inverse?median-value:value-median,status=Math.abs(directional)<=threshold?'flat':directional>0?'up':'down';results.set(point.name,{status,delta:directional,value,median,count:1,suffix})});
    const snapshot={results,median,quartiles,count:values.size};GEO_STATE.evalCache.set(cacheKey,snapshot);return snapshot;
  };

